#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;
vector<double> cs, sn, csi;

void fft(vector<double>& re, vector<double>& im, bool inv) {
    int n = re.size();
    int shiftVal= 32 - (int)log2(n);
    for (int i=1; i<n; i++) {
        int j= (int)reverse((unsigned long long)(i)<<shiftVal) >> shiftVal;
        if (i<j) {
            swap(re[i], re[j]);
            swap(im[i], im[j]);
        }
    }
    for (int len=2; len<=n; len<<=1) {
        int half= len>>1;
        int wIdx= (int)cs.size()/len;
        for (int i=0; i<n; i+=len) {
            for (int j=0, k=0; j<half; j++, k+=wIdx) {
                double wRe= inv ? csi[k] : cs[k];
                double wIm= inv ? sn[k] : -sn[k];
                double uRe= re[i+j];
                double uIm= im[i+j];
                double vRe= re[i+j+half]*wRe - im[i+j+half]*wIm;
                double vIm= re[i+j+half]*wIm + im[i+j+half]*wRe;
                re[i+j]= uRe+vRe;
                im[i+j]= uIm+vIm;
                re[i+j+half]= uRe - vRe;
                im[i+j+half]= uIm - vIm;
            }
        }
    }
    if (inv) {
        for (int i=0; i<n; i++) {
            re[i]/=n;
            im[i]/=n;
        }
    }
}

vector<int> multiplyMod(const vector<int>& a, const vector<int>& b, int m) {
    int needLen= (int)a.size() + (int)b.size() -1;
    int size= 1<<(int)ceil(log2(needLen));
    vector<double> aRe(size), aIm(size), bRe(size), bIm(size);
    for (int i=0; i<(int)a.size(); i++) {
        int x= a[i]%m;
        aRe[i]= x & ((1<<15)-1);
        aIm[i]= x>>15;
    }
    for (int i= (int)a.size(); i<size; i++) {
        aRe[i]=0;
        aIm[i]=0;
    }
    fft(aRe, aIm, false);
    for (int i=0; i<(int)b.size(); i++) {
        int x= b[i]%m;
        bRe[i]= x & ((1<<15)-1);
        bIm[i]= x>>15;
    }
    for (int i= (int)b.size(); i<size; i++) {
        bRe[i]=0;
        bIm[i]=0;
    }
    fft(bRe, bIm, false);
    vector<double> aRe2(size), aIm2(size), bRe2(size), bIm2(size);
    for (int i=0; i<size; i++) {
        int j= (size - i)&(size -1);
        double a1r= (aRe[i]+aRe[j])/2.0;
        double a1i= (aIm[i]-aIm[j])/2.0;
        double a2r= (aIm[i]+aIm[j])/2.0;
        double a2i= (aRe[j]-aRe[i])/2.0;
        double b1r= (bRe[i]+bRe[j])/2.0;
        double b1i= (bIm[i]-bIm[j])/2.0;
        double b2r= (bIm[i]+bIm[j])/2.0;
        double b2i= (bRe[j]-bRe[i])/2.0;
        aRe2[i]= a1r*b1r - a1i*b1i - a2r*b2i - a2i*b2r;
        aIm2[i]= a1r*b1i + a1i*b1r + a2r*b2r - a2i*b2i;
        bRe2[i]= a1r*b2r - a1i*b2i + a2r*b1r - a2i*b1i;
        bIm2[i]= a1r*b2i + a1i*b2r + a2r*b1i + a2i*b1r;
    }
    fft(aRe2, aIm2, true);
    fft(bRe2, bIm2, true);
    vector<int> resArr(needLen);
    for (int i=0; i<needLen; i++) {
        long long aa= (long long)round(aRe2[i]);
        long long bb= (long long)round(bRe2[i]);
        long long cc= (long long)round(aIm2[i]);
        resArr[i]= (int)((aa + (bb<<15) + (cc<<30))%m);
    }
    return resArr;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int totalN, totalK;
    cin >> totalN >> totalK;
    vector<int> v(10,0);
    for (int i=0; i<totalK; i++) {
        int x;
        cin >> x;
        v[x]=1;
    }
    vector<int> ans={1};
    int p= totalN/2;
    while (p>0) {
        if ((p & 1)!=0) {
            ans= multiplyMod(ans, v, MOD);
        }
        v= multiplyMod(v, v, MOD);
        p/=2;
    }
    long long res=0;
    for (int x: ans) {
        res= (res + (long long)x*x)%MOD;
    }
    cout << res << "\n";
    return 0;
}

